export type MethodName = keyof Methods;

/** Events of on(type, fn) and events.recent. */
export interface EventMap {
  /**
   * An image, DEM or vector layer was added, removed or changed.
   */
  layer: LayerEvent;
  /**
   * The selection changed.
   */
  selection: SelectionEvent;
  /**
   * A panel view moved (coalesced to one event per panel per animation frame).
   */
  view: ViewEvent;
  /**
   * A worker job was queued, started, progressed (at most every 250 ms), finished, failed or was cancelled.
   */
  job: JobEvent;
}
export type EventName = keyof EventMap;

/** gisworkbench.api.v2 */
